(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.4)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12 + Math.cos((x-y)*0.009-t*0.35)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.012+t*0.15)*10, w2y = Math.cos(sx*0.014-t*0.2)*10;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.2, 1.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*65, 0.11, 1.4, 0.85],
    [380+Math.sin(t*0.38+4)*100, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 0.95],
    [60+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+4)*50, 0.1, 1.6, 0.8],
    [420+Math.cos(t*0.42+1)*80, 200+Math.sin(t*0.75+2)*60, 0.07, 2.4, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const wave = Math.sin(d*f-t*sp)*w;
    aS += wave;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.8)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+3.1)*w*0.4;
  }
  aS/=8; iS/=8; cS/=8;
  const bg1 = Math.sin(fx*0.035+fy*0.022+t*0.7);
  const bg2 = Math.sin(fx*0.028-fy*0.038+t*0.95);
  const bg3 = Math.sin((fx+fy)*0.1+t*2.2)*0.3;
  const bg4 = Math.sin((fx-fy)*0.085-t*1.8)*0.3;
  const bg = (bg1+bg2)*0.35 + bg3 + bg4;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2);
  const ang = Math.atan2(fy-cy, fx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const lap = Math.sin(fx*0.25)*Math.sin(fy*0.25)+Math.sin(fx*0.18+fy*0.18+t*0.6)*0.5+Math.sin(fx*0.3-fy*0.12+t*0.9)*0.3;
  const rd1 = Math.tanh((aS - iS*0.65 + bg*0.25 + spiral)*2.0);
  const rd2 = Math.tanh((iS - aS*0.5 - bg*0.15 + cS*0.3)*1.8);
  const rdMix = rd1*0.7 + rd2*0.3;
  const cell = Math.tanh(lap*1.2)*0.25;
  const feedback = Math.sin(rdMix*Math.PI*1.5 + cS*2.0)*0.15;
  const blend = rdMix*0.6 + cell*0.2 + feedback*0.2;
  const v = blend*0.5+0.5;
  const glow = Math.max(0, Math.abs(rdMix)-0.5)*2.0;
  const pal = [
    [5,12,52],[12,45,85],[18,85,115],[25,130,130],
    [55,160,120],[140,185,90],[210,190,60],
    [220,150,55],[210,105,60],[185,65,55],
    [140,35,50],[90,18,42],[40,12,48],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const r0 = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0 = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0 = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.82 + Math.sin(rdMix*Math.PI)*0.18;
  const edge = Math.abs(rdMix)>0.65 ? 1.12 : 1.0;
  const hlR = Math.min(255, r0*1.4*glow);
  const hlG = Math.min(255, g0*1.2*glow);
  const hlB = Math.min(255, b0*0.9*glow);
  return [
    Math.min(255, (r0*lum*edge + hlR*0.3))|0,
    Math.min(255, (g0*lum*edge + hlG*0.3))|0,
    Math.min(255, (b0*lum*edge + hlB*0.3))|0
  ];
}
